/** undefined is an unfinished/invalid draft; null is an intentionally empty value. */
export function parseNumber(text: string): number | null | undefined {
  const normalized = text.trim().replace(',', '.');
  if (!normalized) return null;
  if (!/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$/.test(normalized)) return undefined;
  const value = Number(normalized);
  return Number.isFinite(value) ? value : undefined;
}

export function clampNumber(
  value: number | null,
  min = -Infinity,
  max = Infinity
): number | null {
  return value === null ? null : Math.min(max, Math.max(min, value));
}

export function stepNumber(
  value: number | null,
  direction: 1 | -1,
  step = 1,
  min = -Infinity,
  max = Infinity
): number {
  const amount = Number.isFinite(step) && step > 0 ? step : 1;
  const next = (value ?? 0) + direction * amount;
  // Significant-digit rounding removes binary addition noise and supports small scientific steps.
  return Math.min(max, Math.max(min, Number(next.toPrecision(15))));
}
